#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using MVZ2.Managers;
using MVZ2.Resources;
using NGettext;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Localization
{
    public abstract class LanguagePackReaderV0 : ResourcePackReader
    {
        protected LanguagePackReaderV0(MainManager main) : base(main)
        {
        }
        protected Sprite CreateSprite(Texture2D texture2D, SliceData slice, string category)
        {
            try
            {
                var rect = slice.single ? new Rect(0, 0, texture2D.width, texture2D.height) : slice.rect;
                Vector2 pivot = slice.pivot;
                var key = slice.spriteKey.ToString();
                var spr = Main.ResourceManager.CreateSprite(texture2D, rect, pivot, key, category: category);
                return spr;
            }
            catch (Exception e)
            {
                Debug.LogError($"An exception thrown when loading sprite {slice.spriteKey} from a language pack: {e}");
                return Main.ResourceManager.GetDefaultSpriteClone();
            }
        }
        protected void ApplyReadData(ResourcePack pack, PackReadData data, ReadTexture2DMethod textureReader)
        {
            ApplyReadDataCatalogs(pack, data);
            ApplyReadDataTextures(pack, data, textureReader);
        }
        private void ApplyReadDataCatalogs(ResourcePack pack, PackReadData data)
        {
            foreach (var lang in data.catalogs.Keys)
            {
                var packCatalogs = pack.GetOrCreateLanguageCatalogs(lang);
                // 加载文本
                foreach (var pair in data.catalogs[lang])
                {
                    packCatalogs.catalogs.Add(pair.Key, pair.Value);
                }
            }
        }
        private void ApplyReadDataTextures(ResourcePack pack, PackReadData data, ReadTexture2DMethod textureReader)
        {
            foreach (var spriteEntry in data.spriteEntries)
            {
                var texturePath = spriteEntry.texturePath;
                var textureID = spriteEntry.textureID;
                if (!pack.TryGetTexture2D(textureID, out var texture))
                {
                    texture = textureReader(texturePath, textureID.ToString());
                    if (texture == null)
                        continue;
                    pack.AddTexture2D(textureID, texture);
                }

                var slice = spriteEntry.slice;
                var sprite = CreateSprite(texture, slice, GetLanguagePackSpriteCategory(data.Key));
                pack.AddSprite(slice.spriteKey, sprite);
            }
            foreach (var spritesheetEntry in data.spritesheetEntries)
            {
                var texturePath = spritesheetEntry.texturePath;
                var textureID = spritesheetEntry.textureID;
                if (!pack.TryGetTexture2D(textureID, out var texture))
                {
                    texture = textureReader(texturePath, textureID.ToString());
                    if (texture == null)
                        continue;
                    pack.AddTexture2D(textureID, texture);
                }

                var slices = spritesheetEntry.slices;
                for (int i = 0; i < slices.Count; i++)
                {
                    var slice = slices[i];
                    var sprite = CreateSprite(texture, slice, GetLanguagePackSpriteCategory(data.Key));
                    pack.AddSprite(slice.spriteKey, sprite);
                }
            }
        }
        protected delegate Texture2D? ReadTexture2DMethod(string texturePath, string name);
        public const string SPRITE_MANIFEST_FILENAME = "sprite_manifest.json";
        protected class PackReadData
        {
            public string Key;
            public Dictionary<string, Dictionary<string, Catalog>> catalogs = new();
            public List<SpriteEntry> spriteEntries = new();
            public List<SpritesheetEntry> spritesheetEntries = new();

            public PackReadData(string key)
            {
                Key = key;
            }
        }
        protected class SpriteEntry
        {
            public NamespaceID textureID;
            public string texturePath;
            public SliceData slice;

            public SpriteEntry(NamespaceID textureID, string texturePath, SliceData slice)
            {
                this.textureID = textureID;
                this.texturePath = texturePath;
                this.slice = slice;
            }
        }
        protected class SpritesheetEntry
        {
            public NamespaceID textureID;
            public string texturePath;
            public List<SliceData> slices = new();

            public SpritesheetEntry(NamespaceID textureID, string texturePath)
            {
                this.textureID = textureID;
                this.texturePath = texturePath;
            }
        }

        protected class SliceData
        {
            public Rect rect;
            public Vector2 pivot;
            public float pixelsPerUnit;
            public uint extrude;
            public bool single;
            public SpriteMeshType meshType;
            public Vector4 border;
            public SpriteLookupKey spriteKey;

            public SliceData(SpriteLookupKey spriteKey)
            {
                this.spriteKey = spriteKey;
            }
        }
    }
}
